CREATE TABLE public.marketing_photo_notifications (inspection_id uuid PRIMARY KEY REFERENCES public.inspections(id) ON DELETE CASCADE, status text NOT NULL CHECK(status IN ('sending','sent','failed')), claimed_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz, message_ts text, error_message text);
GRANT ALL ON public.marketing_photo_notifications TO service_role;
ALTER TABLE public.marketing_photo_notifications ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.claim_marketing_photo_notification(p_inspection_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE claimed uuid; BEGIN INSERT INTO public.marketing_photo_notifications(inspection_id,status) VALUES(p_inspection_id,'sending') ON CONFLICT(inspection_id) DO UPDATE SET status='sending',claimed_at=now(),error_message=null WHERE marketing_photo_notifications.status='failed' OR (marketing_photo_notifications.status='sending' AND marketing_photo_notifications.claimed_at < now()-interval '5 minutes') RETURNING inspection_id INTO claimed; RETURN claimed IS NOT NULL; END; $$;
REVOKE ALL ON FUNCTION public.claim_marketing_photo_notification(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_marketing_photo_notification(uuid) TO service_role;